package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTotal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal // PIC 9(10)V99 len=12 = 0
var WsNewCount int64 // PIC 99 len=2 = 0
var WsShipCount int64 // PIC 99 len=2 = 0
var WsCancelCount int64 // PIC 99 len=2 = 0
var WsInvalid int64 // PIC 99 len=2 = 0
var WsBadQty int64 // PIC 99 len=2 = 0
var WsQtyEd string // PIC ZZ9 len=3
var WsPriceEd string // PIC Z,ZZ9.99 len=8
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var curRec OrderRec
var orderLines []string
var orderIdx int

func isInputDone() bool { return WsEofFlag == "Y" }

func fmt99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func storePic(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	scaled := t.Shift(scale).Truncate(0).IntPart()
	mod := int64(1)
	for i := 0; i < intDigits+int(scale); i++ {
		mod *= 10
	}
	r := scaled % mod
	return decimal.New(r, -scale)
}

func parseQty(s string) int64 {
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return n
}

func parsePrice(s string) decimal.Decimal {
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -2)
}

func parseRecord(line string) OrderRec {
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	var r OrderRec
	r.OrId = line[0:5]
	r.OrStat = line[5:6]
	r.OrQty = parseQty(line[6:9])
	r.OrPrice = parsePrice(line[9:15])
	return r
}

func formatEdited(v decimal.Decimal, pic string) string {
	// find scale
	scale := 0
	dot := strings.Index(pic, ".")
	var intPic string
	var fracLen int
	if dot >= 0 {
		intPic = pic[:dot]
		fracPart := pic[dot+1:]
		fracLen = len(fracPart) // all 9s
		scale = fracLen
	} else {
		intPic = pic
	}
	// count integer slots
	nSlots := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			nSlots++
		}
	}
	// scaled integer truncate toward zero
	t := v.Truncate(int32(scale))
	neg := t.IsNegative()
	absT := t.Abs()
	shifted := absT.Shift(int32(scale)).Truncate(0)
	sInt := shifted.IntPart() // >=0
	// split
	pow10 := int64(1)
	for i := 0; i < scale; i++ {
		pow10 *= 10
	}
	var intPart int64
	var fracPart int64
	if scale > 0 {
		fracPart = sInt % pow10
		intPart = sInt / pow10
	} else {
		intPart = sInt
	}
	// int digits with overflow drop
	sDigits := fmt.Sprintf("%d", intPart)
	if len(sDigits) > nSlots {
		sDigits = sDigits[len(sDigits)-nSlots:]
	}
	// left pad with zeros to nSlots
	if len(sDigits) < nSlots {
		sDigits = strings.Repeat("0", nSlots-len(sDigits)) + sDigits
	}
	// find first nonzero
	firstNZ := nSlots // N means all zero
	for i := 0; i < nSlots; i++ {
		if sDigits[i] != '0' {
			firstNZ = i
			break
		}
	}
	// build integer formatted
	var b strings.Builder
	slotIdx := 0
	// track whether any printed digit appeared to the left (for comma)
	printedDigit := false
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == 'Z' || ch == '9' {
			d := sDigits[slotIdx]
			if ch == 'Z' {
				if slotIdx < firstNZ {
					b.WriteByte(' ')
				} else {
					b.WriteByte(d)
					printedDigit = true
				}
			} else {
				b.WriteByte(d)
				printedDigit = true
			}
			slotIdx++
		} else if ch == ',' {
			if printedDigit {
				b.WriteByte(',')
			} else {
				// check if any non-suppressed digit to left? printedDigit covers it
				// also if remaining? COBOL: comma in suppressed zone -> space
				b.WriteByte(' ')
			}
		} else {
			b.WriteByte(ch)
		}
	}
	if dot >= 0 {
		b.WriteByte('.')
		fracStr := fmt.Sprintf("%d", fracPart)
		if len(fracStr) < fracLen {
			fracStr = strings.Repeat("0", fracLen-len(fracStr)) + fracStr
		}
		if len(fracStr) > fracLen {
			fracStr = fracStr[len(fracStr)-fracLen:]
		}
		b.WriteString(fracStr)
	}
	_ = neg
	// values are non-negative in this program; ignore sign
	return b.String()
}

func loadOrderFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			orderLines = nil
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	// split preserving lines
	text := string(data)
	parts := strings.Split(text, "\n")
	lines := make([]string, 0, len(parts))
	for i, p := range parts {
		if i == len(parts)-1 && p == "" {
			// trailing empty due to final newline: skip
			continue
		}
		// strip trailing \r
		if strings.HasSuffix(p, "\r") {
			p = p[:len(p)-1]
		}
		lines = append(lines, p)
	}
	// Handle case file ends with \r\n and split left \r? already handled.
	// If file was empty, lines may be empty.
	orderLines = lines
}

func MAINPARA() {
	WsEofFlag = "N"
	WsTotal = decimal.NewFromInt(0)
	WsGrand = decimal.NewFromInt(0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0
	loadOrderFile()
	orderIdx = 0
	// OPEN INPUT ORDER-FILE
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE ORDER-FILE
	SUMMARYPARA()
}

func READPARA() {
	if orderIdx >= len(orderLines) {
		WsEofFlag = "Y"
		return
	}
	line := orderLines[orderIdx]
	orderIdx++
	curRec = parseRecord(line)
}

func PROCESSPARA() {
	WsTotal = decimal.NewFromInt(0)
	if curRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Fprintln(os.Stdout, curRec.OrId+" BAD QTY")
	} else if curRec.OrStat == "N" {
		comp := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice)
		comp = comp.Truncate(2)
		WsTotal = storePic(comp, 8, 2)
		WsNewCount = (WsNewCount + 1) % 100
		SHOWPARA()
	} else if curRec.OrStat == "S" {
		comp := decimal.NewFromInt(curRec.OrQty).Mul(curRec.OrPrice).Mul(decimal.NewFromFloat(1.05))
		comp = comp.Round(2)
		WsTotal = storePic(comp, 8, 2)
		WsShipCount = (WsShipCount + 1) % 100
		SHOWPARA()
	} else if curRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		SHOWPARA()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Fprintln(os.Stdout, curRec.OrId+" BAD STATUS "+curRec.OrStat)
	}
	WsGrand = storePic(WsGrand.Add(WsTotal).Truncate(2), 10, 2)
	READPARA()
}

func SHOWPARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(curRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(curRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Fprintln(os.Stdout, curRec.OrId+" "+curRec.OrStat+" "+WsQtyEd+" "+WsPriceEd+" "+WsTotalEd)
}

func SUMMARYPARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Fprintln(os.Stdout, "NEW: "+fmt99(WsNewCount)+" SHIPPED: "+fmt99(WsShipCount)+" CANCELLED: "+fmt99(WsCancelCount))
	fmt.Fprintln(os.Stdout, "INVALID: "+fmt99(WsInvalid)+" BAD QTY: "+fmt99(WsBadQty))
	fmt.Fprintln(os.Stdout, "GRAND TOTAL: "+WsGrandEd)
}

func main() {
	MAINPARA()
}
